      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What Is RenOS?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "RenOS is an AI operating system for teams, and the governance layer for AI at work. It gives your people one workspace across many AI models, routes each task by your rules, explains every decision in plain language and writes an audit entry automatically."
          }
        },
        {
          "@type": "Question",
          "name": "How Is It Different from a Single AI Assistant?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "An assistant answers questions. RenOS sits across every model your team uses and adds the policy layer, audit trail and admin view across all of them."
          }
        },
        {
          "@type": "Question",
          "name": "Which AI Models Does It Work With?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Frontier and open models through one workspace, plus your own keys on Enterprise and local models on your own hardware."
          }
        },
        {
          "@type": "Question",
          "name": "Where Does Our Data Go?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You choose which models and suppliers each task may use, by data sensitivity, task type or role. Every choice is logged with its reason."
          }
        },
        {
          "@type": "Question",
          "name": "Can It Run in Our Own Environment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Private deployment runs RenOS on your own infrastructure with local models."
          }
        },
        {
          "@type": "Question",
          "name": "Is AI Coaching Part of RenOS?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Coaching is now part of RenOS as coaching agents, covering sales, leadership and frontline skill building in the same platform."
          }
        },
        {
          "@type": "Question",
          "name": "How Do We Get Started?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Start with a 60-day pilot: one team, one real workflow, up to 15 seats and a written success plan. Contact Vocom to set it up, or apply on the RenOS website."
          }
        }
      ]
